#[test]
fn company_parser_preserves_conservative_source_policy() {
    for (raw, expected) in [
        (" sc012345 ", Some("SC012345")),
        ("527227", None),
        ("NI 016363", None),
        ("AAAAAAAA", None),
        ("00527227", Some("00527227")),
